:root { font-family: system-ui, sans-serif; color: #172b40; background: #f4f7fa; }
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #dce4ec; border-radius: 12px; }
h1 { margin-top: 0; overflow-wrap: anywhere; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.create-controls { display: flex; gap: 12px; }
input { min-width: 0; flex: 1; padding: 10px; border: 1px solid #8293a5; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 1px solid #2359a0; border-radius: 6px; background: #2359a0; color: white; font: inherit; cursor: pointer; }
button:hover { background: #17477f; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #eea52a; outline-offset: 3px; }
#project-list { margin-top: 32px; }
.project-row { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 20px; padding: 16px 0; border-bottom: 1px solid #dce4ec; }
.project-row span { overflow-wrap: anywhere; min-width: 0; }
.project-row button { flex-shrink: 0; }
section[aria-label="Tasks"] { margin-top: 28px; }
#task-filter, #project-filter { margin-bottom: 16px; padding: 8px; font: inherit; }
label[for="task-filter"], label[for="project-filter"] { margin-top: 24px; }
.task-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 16px 0; border-bottom: 1px solid #dce4ec; }
