:root { font-family: system-ui, sans-serif; color: #172b40; background: #f4f7fa; }
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #dce4ec; border-radius: 12px; }
h1 { margin-top: 0; overflow-wrap: anywhere; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.create-controls { display: flex; gap: 12px; }
input { min-width: 0; flex: 1; padding: 10px; border: 1px solid #8293a5; border-radius: 6px; font: inherit; }
